"""Self-contained full-scene comparison; explicit overview scaling and physical-pixel crops."""
import json, statistics
from pathlib import Path
ROOT=Path('artifacts/appearance-probe/regional-scene')

def main():
    data=json.loads((ROOT/'report.json').read_text())
    summaries=[]
    for res in [0,1]:
        rows=[r for r in data['rows'] if r['resolution']==res];timed=[r for r in rows if r['timings']]
        pair=lambda r,key,slots:statistics.mean(r['timings'][i][key]['median'] for i in slots)
        summaries.append({'resolution':res,'triangle_reduction_range':[min(1-r['adaptive']['triangles']/r['full']['triangles'] for r in rows),max(1-r['adaptive']['triangles']/r['full']['triangles'] for r in rows)],'gpu_full_ms':statistics.median(pair(r,'gpu_ms',[0,2]) for r in timed),'gpu_adaptive_ms':statistics.median(pair(r,'gpu_ms',[1,3]) for r in timed),'gpu_paired_ratio':statistics.median(pair(r,'gpu_ms',[1,3])/pair(r,'gpu_ms',[0,2]) for r in timed),'serial_full_ms':statistics.median(pair(r,'serial_ms',[0,2]) for r in timed),'serial_adaptive_ms':statistics.median(pair(r,'serial_ms',[1,3]) for r in timed),'serial_paired_ratio':statistics.median(pair(r,'serial_ms',[1,3])/pair(r,'serial_ms',[0,2]) for r in timed),'planning_full_us':statistics.median(r['cpu_planning']['full_us']['median'] for r in rows),'planning_adaptive_us':statistics.median(r['cpu_planning']['adaptive_us']['median'] for r in rows),'foreground_rmse_median':statistics.median(r['error_vs_full']['foreground_rmse'] for r in rows),'foreground_rmse_max':max(r['error_vs_full']['foreground_rmse'] for r in rows),'visible_mixed_range':[min(sum(o['geometry_pixels']>0 and o['summary_pixels']>0 for o in r['visible_regions']) for r in rows),max(sum(o['geometry_pixels']>0 and o['summary_pixels']>0 for o in r['visible_regions']) for r in rows)]})
    data['summary']=summaries;(ROOT/'summary.json').write_text(json.dumps(summaries,indent=2))
    html='''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ignis · regiões na mesma cena</title>
<style>*{box-sizing:border-box}body{margin:30px auto;padding:0 24px;max-width:1600px;background:#101720;color:#e4edf4;font:15px/1.5 system-ui,sans-serif}h1{font-size:32px;line-height:1.2}h2{font-size:18px}.eyebrow{color:#dfb47c;font-size:12px;letter-spacing:2px}.panel{border:1px solid #34465b;background:#172231;padding:18px;border-radius:12px;margin:18px 0}.controls{display:flex;gap:15px;flex-wrap:wrap;align-items:end}label{display:grid;gap:4px;color:#b6c5d5}button,select{font:inherit;color:#e5eef5;background:#263b52;padding:8px;border:1px solid #4c6885;border-radius:6px}button{cursor:pointer}input{width:min(650px,80vw)}.overview{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.overview canvas{display:block;width:100%;height:auto;cursor:crosshair}.crops{display:flex;gap:15px;flex-wrap:wrap}.crops canvas{image-rendering:pixelated;max-width:none;display:block}.scroll{overflow:auto;max-width:100%}figure{margin:0}figcaption{font-weight:600;margin-bottom:7px}.note{font-size:13px;color:#afc1d0}.stat{font-variant-numeric:tabular-nums;color:#f1c791}table{border-collapse:collapse;min-width:650px}td,th{text-align:left;padding:8px 18px 8px 0;border-bottom:1px solid #34465b}#status{color:#ffbd84}@media(max-width:850px){.overview{grid-template-columns:1fr}body{padding:0 12px}}</style>
<body><div class="eyebrow">IGNIS · EAF-74 · LABORATÓRIO GRÁFICO</div><h1>Geometria e resumos, juntos na cena</h1>
<p>96 instâncias — 32 pedras, 32 baús e 32 árvores — sobre terreno, do primeiro plano até 1200 unidades. Cada asset tem regiões independentes e caches locais preparados antes do percurso. Câmera afasta e retorna; cor e profundidade são compostas no mesmo render.</p>
<div class="panel controls"><label>Render físico<select id="resolution"><option value="0">3456 × 2234 · resolução física da tela</option><option value="1">1728 × 1117 · resolução reduzida</option></select></label><button id="play">Reproduzir percurso</button><button id="mixed">Inspecionar objeto com mistura visível</button><label>Ampliação do recorte<select id="zoom"><option value="1">1× físico</option><option value="2">2× explícito</option><option value="4">4× explícito</option></select></label><div><input id="frame" type="range" min="0" value="6"><p id="pose" class="stat"></p></div></div>
<p id="counts" class="stat"></p><p id="status"></p>
<div class="overview" id="overview"></div><p class="note">Visão geral reduzida para caber na página. Clique em qualquer imagem para comparar o mesmo recorte nas versões abaixo. Esta redução de apresentação não muda a resolução do render nem a seleção.</p>
<div class="panel"><p id="focus"></p><div class="scroll"><div class="crops" id="crops"></div></div><p id="display" class="note"></p></div>
<div class="panel"><h2>Medições nesta posição</h2><p id="quality"></p><p id="timing"></p><p id="cpu"></p><p id="reference"></p><div class="scroll"><table id="objects"></table></div></div>
<div class="panel"><h2>Comparação do percurso</h2><div class="scroll"><table id="summary"></table></div><p class="note">Mediana das razões calculadas por pose com os controles duplicados: abaixo de100% custa menos; acima custa mais. Não é a razão entre duas medianas independentes. GPU = passe completo da cena. Tempo serial = seleção, upload, codificação, submissão e espera da GPU; sem captura/PNG. É um teste sincronizado, não FPS de um jogo com CPU/GPU sobrepostas.</p><p id="memory"></p></div>
<div class="panel"><h2>O que este experimento testa</h2><p>Azul no mapa significa geometria; laranja significa resumo; cinza é terreno. A escolha usa limites projetados de aresta e texel em pixels físicos, entrada abaixo de0,75pixel e retorno em1pixel. Materiais brilhantes2–4 permanecem como geometria: a média de normais deste cache não preservou seus picos especulares. A região pode cobrir vários pixels: seu cache conserva variação espacial, enquanto os triângulos substituídos são subpixel. As regiões são construídas por posição e material; não são recortes retangulares colados sobre a imagem.</p><p>Os resumos agora guardam cor, normal, cobertura e profundidade em seis vistas locais, com mipmaps próprios. O material GGX é avaliado na execução para geometria e resumos. Isto é uma representação experimental diferente do atlas angular de radiância anterior: permite profundidade local e compartilhamento por instância, mas média de normais não equivale a integrar uma BRDF.</p><p>Há uma camada por vista, escolha discreta da vista e cobertura opaca aproximada. Esses limites podem produzir falhas de silhueta, desoclusão e pequenas transições. O critério subpixel sozinho não garante erro visual zero. A câmera usa profundidade invertida; a inversão da ordem de desenho e repetição foram verificadas. A luz permanece fixa neste percurso para isolar distância; não há sombras projetadas, GI, vento, streaming ou deformação.</p><p>A referência integrada usa4 amostras/pixel em posições selecionadas. As três imagens principais usam1 amostra/pixel e o mesmo material/câmera. O erro de foreground exclui o terreno vazio; as métricas por objeto usam sua máscara da geometria completa. Também entram no erro pixels extras criados pelo resumo. O player reproduz capturas offline, não mede a velocidade do navegador nem renderiza a engine ao vivo.</p></div>
<script>
const DATA=__DATA__;
const $=id=>document.getElementById(id),names=['Pedra','Baú','Árvore'];
let interval=null,epoch=0,loaded=null,focus=[.5,.5],focusId=null;
const fmt=(v,n=3)=>Number(v).toFixed(n);
function rows(){return DATA.rows.filter(r=>r.resolution===Number($('resolution').value))}
function current(){return rows()[Number($('frame').value)]}
function cellRow(values,head=false){const tr=document.createElement('tr');for(const v of values){const td=document.createElement(head?'th':'td');td.textContent=String(v);tr.append(td)}return tr}
function crop(){if(!loaded)return;const r=current(),z=Number($('zoom').value),dpr=window.devicePixelRatio||1;
 const o=r.visible_regions.find(o=>o.id===focusId);if(o){focus=[(o.bbox[0]+o.bbox[2])/2/r.size[0],(o.bbox[1]+o.bbox[3])/2/r.size[1]]}
 const side=512,x=Math.round(Math.max(0,Math.min(r.size[0]-side,focus[0]*r.size[0]-side/2))),y=Math.round(Math.max(0,Math.min(r.size[1]-side,focus[1]*r.size[1]-side/2)));
 const figures=loaded.map((img,i)=>{const fig=document.createElement('figure'),cap=document.createElement('figcaption'),c=document.createElement('canvas');cap.textContent=['Geometria completa','Seleção por região','Mapa: azul geometria / laranja resumo','Referência integrada · 4 spp'][i];c.width=side;c.height=side;c.style.width=`${side*z/dpr}px`;c.style.height=`${side*z/dpr}px`;c.getContext('2d').drawImage(img,x,y,side,side,0,0,side,side);fig.append(cap,c);return fig});$('crops').replaceChildren(...figures);
 $('focus').textContent=o?`Objeto ${o.id} · ${names[DATA.objects[o.id-1].asset]} · ${o.geometry_pixels} pixels de geometria + ${o.summary_pixels} pixels de resumo visíveis. Caixa na imagem: ${o.bbox[2]-o.bbox[0]} × ${o.bbox[3]-o.bbox[1]} px.`:'Recorte escolhido na imagem. Clique na visão geral ou inspecione um objeto com mistura visível.';
 $('display').textContent=`Recorte512² em (${x}, ${y}) do render ${r.size.join(' × ')}. DPR ${dpr}: ${fmt(512*z/dpr,1)} pixels CSS de lado; ampliação física ${z}×.`;
}
function show(){const r=current();$('frame').max=rows().length-1;const e=++epoch;loaded=null;
 $('pose').textContent=`${r.way==='away'?'Afastando':'Retornando'} · câmera (${r.eye.map(v=>fmt(v,1)).join(', ')}) · posição ${Number($('frame').value)+1}/${rows().length}`;
 const visibleMixed=r.visible_regions.filter(o=>o.geometry_pixels>0&&o.summary_pixels>0).length;
 $('counts').textContent=`${r.full.visible_objects} objetos no frustum · ${visibleMixed} com mistura visível · ${r.adaptive.mixed_objects} com regiões selecionadas de ambos os tipos, incluindo partes ocultas. Triângulos: ${r.full.triangles.toLocaleString('pt-BR')} → ${r.adaptive.triangles.toLocaleString('pt-BR')} (${fmt((1-r.adaptive.triangles/r.full.triangles)*100,1)}% a menos).`;
 const er=r.error_vs_full;$('quality').textContent=`Erro RGB linear contra geometria1spp: foreground ${fmt(er.foreground_rmse,5)} · imagem inteira ${fmt(er.frame_rmse,5)}. ${er.id_mismatch_pixels} pixels diferem no ID visível (inclui silhueta/oclusão). Menor erro é melhor; não é porcentagem de qualidade.`;
 const t=r.timings;const avg=(key,a,b)=>(t[a][key].median+t[b][key].median)/2;
 $('timing').textContent=t?`GPU da cena: geometria ${fmt(avg('gpu_ms',0,2))} ms · regional ${fmt(avg('gpu_ms',1,3))} ms. Serial com seleção: geometria ${fmt(avg('serial_ms',0,2))} ms · regional ${fmt(avg('serial_ms',1,3))} ms. Controles GPU: ${t.map(t=>fmt(t.gpu_ms.median)).join(' / ')} ms (G/R/G/R).`:'Tempos não medidos nesta posição; disponíveis nos pontos marcados a cada3 passos e na volta.';
 $('cpu').textContent=`Preparação CPU mediana: geometria ${fmt(r.cpu_planning.full_us.median,1)} µs · regional ${fmt(r.cpu_planning.adaptive_us.median,1)} µs. Chamadas: ${r.full.draw_calls} → ${r.adaptive.draw_calls}. Upload de instâncias: ${fmt(r.adaptive.upload_bytes/1024,1)} KiB, além do uniform de câmera.`;
 $('reference').textContent=r.reference_full_error?`Contra referência4spp: geometria ${fmt(r.reference_full_error.foreground_rmse,5)} · regional ${fmt(r.reference_adaptive_error.foreground_rmse,5)} RMSE foreground.`:'Referência4spp não capturada nesta posição; comparação principal usa1spp nos dois métodos.';
 const top=er.objects.filter(o=>o.pixels>=8).sort((a,b)=>b.rmse-a.rmse).slice(0,6);
 $('objects').replaceChildren(cellRow(['Maior erro por objeto','Pixels na referência','RMSE RGB'],true),...top.map(o=>cellRow([`${o.id} · ${names[DATA.objects[o.id-1].asset]}`,o.pixels,fmt(o.rmse,5)])));
 $('status').textContent='Carregando cena…';
 Promise.all((r.reference_full_error?['full','adaptive','map','reference']:['full','adaptive','map']).map(s=>new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=`${r.id}_${s}.png`}))).then(images=>{if(e!==epoch)return;loaded=images;const figures=images.slice(0,2).map((img,i)=>{const fig=document.createElement('figure'),cap=document.createElement('figcaption'),c=document.createElement('canvas');cap.textContent=i?'Seleção por região · visão geral reduzida':'Geometria completa · visão geral reduzida';c.width=r.size[0];c.height=r.size[1];c.getContext('2d').drawImage(img,0,0);c.onpointerdown=ev=>{const b=c.getBoundingClientRect();focusId=null;focus=[(ev.clientX-b.left)/b.width,(ev.clientY-b.top)/b.height];crop()};fig.append(cap,c);return fig});$('overview').replaceChildren(...figures);crop();$('status').textContent=''}).catch(()=>{if(e===epoch)$('status').textContent='Falha ao carregar captura.'});
}
function stop(){if(interval!==null)clearInterval(interval);interval=null;$('play').textContent='Reproduzir percurso'}
$('frame').oninput=show;$('resolution').onchange=()=>{stop();show()};$('zoom').onchange=crop;
$('mixed').onclick=()=>{const candidates=current().visible_regions.filter(o=>o.geometry_pixels&&o.summary_pixels);candidates.sort((a,b)=>Math.min(b.geometry_pixels,b.summary_pixels)-Math.min(a.geometry_pixels,a.summary_pixels));focusId=candidates[0]?.id??null;crop()};
$('play').onclick=()=>{if(interval!==null){stop();return}$('play').textContent='Pausar';interval=setInterval(()=>{$('frame').value=String((Number($('frame').value)+1)%rows().length);show()},350)};
window.addEventListener('resize',crop);
$('summary').replaceChildren(cellRow(['Render','GPU regional / geometria','Serial regional / geometria','Redução de triângulos','RMSE foreground mediano'],true),...DATA.summary.map(s=>cellRow([s.resolution?'1728 × 1117':'3456 × 2234',`${fmt(s.gpu_paired_ratio*100,1)}% do custo`,`${fmt(s.serial_paired_ratio*100,1)}% do custo`,s.triangle_reduction_range.map(x=>fmt(x*100,1)+'%').join(' a '),fmt(s.foreground_rmse_median,5)])));
$('memory').textContent=`Cache GPU compartilhado pelos96 objetos: ${fmt(DATA.cache_allocated_bytes/1048576,2)} MiB. Geometria + índices, incluindo terreno: ${fmt((DATA.vertex_bytes+DATA.index_bytes)/1048576,2)} MiB. Dados por asset: ${DATA.assets.map(a=>`${a.name}: ${a.regions} regiões / ${fmt(a.cache_bytes/1048576,2)} MiB`).join(' · ')}. Payload não inclui targets, metadados, buffers de instâncias, driver ou staging.`;
show();
</script></body></html>'''
    (ROOT/'index.html').write_text(html.replace('__DATA__',json.dumps(data,separators=(',',':'))))
    print(json.dumps(summaries,indent=2))
if __name__=='__main__':main()
